C = dict(id='GL-09', title='Nanosatellites and Space Data', group='Digital and Technology', level=5,
 summary='Understand how small satellites work and use open Earth-observation data to answer a real question about land, water or weather.',
 outcomes=['Explain what a nanosatellite is, how it orbits and what it can sense.', 'Download and open a free open-data image set and read its labels.', 'Analyse change over time using bands, dates and simple indices.', 'Create a one-page data story for a decision maker with maps and numbers.', 'Evaluate the limits of the data: cloud, resolution and revisit time.'],
 task='Answer one real land, water or weather question with free open satellite data and present the result with its limits.',
 cond='A computer, a free mapping and image tool, open data from a public space agency or open archive, a free spreadsheet, a mentor and a peer circle. About 12 weeks part-time.',
 std='Data source and licence recorded; two dates compared with a calculated index; limits stated; a decision maker confirms the one-page story is understandable.',
 who='Environment, farming, planning and data learners; students; analysts moving into space data.', req='Basic spreadsheet skills.',
 safety='Use only open data and follow its licence. Do not try to identify individuals or private activity from images.',
 mods=[
 ('What a nanosatellite is', 'Small satellites make space affordable. Learn the building blocks.', ['Classes by mass: nano is roughly 1 to 10 kg; a common cube is 10 cm per side.', 'Parts: power from panels, computer, radio, sensors and a way to point.', 'Orbit height decides how often it passes and how sharp the picture is.', 'Why many small satellites together can give frequent views.'], 'A 3-unit cube is 30 cm long. Three units have 3 times the volume of one unit (3 litres instead of 1 litre): more room for a camera and battery.', 'Draw a block diagram with arrows showing power, data and commands.', 'Diagram shows all main parts and what flows between them.'),
 ('Orbits and passes', 'An orbit decides what is seen and when.', ['Low Earth orbit is a few hundred kilometres; one lap takes about 90 minutes.', 'Revisit time: how long until the satellite sees the same place again.', 'A radio pass over a ground station lasts only minutes, so data waits on board.', 'Time of day affects light and shadow.'], 'At 90 minutes a lap there are 16 laps a day (24 divided by 1.5). Each lap crosses a different strip.', 'Find a free pass predictor and note three passes over your town.', 'Record three passes with time and direction.'),
 ('Sensors and bands', 'Different light bands reveal different things.', ['Visible bands show what the eye sees; near-infrared shows plant health.', 'Resolution is the size of one pixel (one small square of the image). A pixel can be 10 m or 3 m wide.', 'Radar sees through cloud and at night.', 'Match sensor to question.'], 'A pixel of 10 m covers 100 square metres, so a house of 80 square metres is smaller than one pixel.', 'List four questions and the best sensor for each.', 'Match each question to a sensor with a reason.'),
 ('Finding and opening open data', 'Open data is free but has licences and labels.', ['Search public archives; choose area and dates.', 'Record the source, licence and date for every file.', 'Open the image in a free tool; check bands and coordinates.', 'Keep files small by cropping to your area.'], 'Cropping a scene of 100 km by 100 km down to 10 km by 10 km leaves 1% of the area and a far lighter file.', 'Download two dates for your area and record the licence.', 'Source and licence recorded; files open correctly.'),
 ('Reading change over time', 'Compare two dates with a simple index.', ['A plant index is (near-infrared minus red) divided by (near-infrared plus red).', 'Values near 0 are bare ground; higher values are greener.', 'Check cloud and season before you compare.', 'Compare same season in different years.'], 'Near-infrared 0.50, red 0.10: index = 0.40 / 0.60 = 0.67, healthy vegetation. Later 0.35 and 0.20: 0.15 / 0.55 = 0.27, much lower.', 'Calculate the index for 10 sample points on two dates.', '10 points calculated; one clear change found.'),
 ('Quality and limits', 'Every dataset has limits. Name them.', ['Cloud and haze block views; mark them.', 'Resolution limits what you can claim.', 'Revisit gaps hide short events.', 'Ground truth: check with a walk or local report.'], 'The scene shows a lower index in March, but cloud covered 30% of it: say so, and test with another date.', 'Write a limits table with five rows.', 'Give each row a limit, an effect and a check.'),
 ('The one-page data story', 'Decision makers need the answer, a picture and a next step.', ['Headline sentence with a number.', 'Two maps: before and after, same scale.', 'Three bullet findings with units.', 'Limits and one recommended action.'], 'Headline: "Green cover fell 12% in the east block between last October and this October; check irrigation."', 'Create your one-page story.', 'Answer first; maps same scale; limits stated.'),
 ('Review and next 90 days', 'Test the story with a real reader and plan growth.', ['Show it to a decision maker; ask what they would do next.', 'Give two peers written feedback.', 'Share your data-source list with the next learner.', 'Plan 90 days: another area, another index, a skill to add.'], 'A reader asks "so what?". You add a recommended action in the headline.', 'Run the review and write the plan.', 'Record a reader quote and date the plan.')],
 quiz=[('What is a nanosatellite?', 'A satellite of roughly 1 to 10 kg, often built from small cube units.'), ('Why is low orbit useful?', 'Closer means sharper pictures and shorter radio delay.'), ('What is revisit time?', 'How long until the satellite sees the same place again.'), ('Why use radar?', 'It sees through cloud and at night.'), ('How is the plant index calculated?', '(near-infrared minus red) divided by (near-infrared plus red).'), ('Why record licence?', 'It says how you may use and share the data.'), ('Why check cloud?', 'Cloud changes the numbers and can fake a change.'), ('What goes in a headline?', 'The answer, with a number.'), ('What is ground truth?', 'A check on the ground that confirms what the image seems to show.'), ('Name one limit of 10 m pixels.', 'Objects smaller than 10 m cannot be seen as separate things.')],
 rubric=[('Data handling', 'Source, licence and dates recorded', 'Files cropped, named and backed up neatly'), ('Method', 'Index calculated correctly on two dates', 'Method repeated on a third date and checked'), ('Limits', 'Five limits named', 'Limits changed the conclusion'), ('Story', 'Answer first with maps', 'Decision maker acted on it'), ('Reflection', 'Three lessons written', 'Lessons shaped the next plan')],
 jobs=[('Earth-observation analyst', 'Turns images into decisions'), ('Environmental monitoring assistant', 'Tracks water, land and green cover'), ('Agri data assistant', 'Reads crop condition maps'), ('Planning assistant', 'Maps land change for local bodies')],
 next='Drones: Operations and Applications; Internet of Things; Artificial Intelligence in Practice.',
 local='Open-data licences and what you may publish differ by country and agency: read each licence.',
 evidence='Your evidence: data log with licences, two-date index table, limits table, one-page story and reader quote.',
 ladder=[('Basics of space', 'Explain satellite and orbit in plain words, and why some satellites move across the sky while others hover over one place. Notes: use a sky-watching app to find one pass. Standard: three sentences a friend can repeat.'), ('Awareness of space data', 'Describe what open satellite data exists (images, weather, ocean, land cover), who publishes it and what licence it carries. Notes: browse a public archive together and write down the licence. Standard: three datasets named with what each shows and its licence.'), ('First data task', 'Open and read an image: find a place, read its bands or colours, and note its date, scale and cloud cover. Notes: practise with a small crop of your own town. Standard: a note listing date, resolution and one limit of the image.'), ('Analyst basics', 'Compare the same place on two dates and describe the change, stating cloud, season and resolution limits. Notes: spreadsheet only, with a table of the numbers you read. Standard: change described in a sentence with a number and one reason it may be wrong.'), ('Specialist', 'Answer one real land, water or weather question with free open satellite data and present the result with its limits. Notes: choose a question you can check on the ground, such as a lake edge or a green area. Standard: question, data source, method, result and three stated limits on one page.'), ('Advanced analyst', 'Build a time series and automate the repeated steps with free tools, with a data log and a check against ground truth. Notes: script the download and the table, and test the script on a second place. Standard: the series covers at least 12 dates and the script runs unaided on another place.'), ('Super expert', 'Lead method and teach teachers. Notes: review data sources yearly.')])

C['deep'] = dict(mods=[
 ('Thinking "nano" means weak; many missions only need small, cheap sensors.', 'A 3-unit cube with a small camera is enough to study vegetation patterns, but it cannot follow a single plane.', 'What is one thing a small satellite can do well and one thing it cannot?'),
 ('Forgetting that revisit time limits how fast you can see change.', 'A 5-day revisit means a flood lasting two days may never be seen.', 'What revisit time does your question need?'),
 ('Picking a sensor because it is famous, not because it fits.', 'Cloudy season: choose radar, because optical shows only cloud.', 'Which sensor did you pick and why?'),
 ('Ignoring licence terms on open data.', 'Licence needs credit and forbids resale; add the credit line to the story.', 'What is the licence of your data?'),
 ('Comparing a wet-season image to a dry-season one.', 'Index fell from 0.62 to 0.35, but the second date is dry season. Compare the same month across years.', 'Are your two dates in the same season?'),
 ('Hiding the limits.', 'Limits row: "30% of the scene under cloud; effect: index too low; check: use clear dates".', 'What is your biggest limit?'),
 ('A map without a scale or date.', 'Both maps use the same scale bar and are dated; readers can compare at a glance.', 'Do both maps share scale and legend?'),
 ('Ending without a decision.', 'The recommended action: "Inspect the east block this week".', 'What should the reader do next?')],
 gloss=[('Pixel', 'The smallest square in an image.'), ('Band', 'A slice of light the sensor records, such as red.'), ('Revisit time', 'Time until the satellite sees the same place again.'), ('Index', 'A number made from bands to describe something like plant health.'), ('Ground truth', 'A check on the ground.'), ('Open data', 'Data anyone may use under a stated licence.')],
 cases=[('The cloudy month', 'Your chosen month has 60% cloud.', 'What do you do?', 'Choose clearer dates, use radar if available, or say the question cannot be answered with that month.'),
        ('The small plot', 'A farmer asks about a 400 square metre plot with 10 m pixels.', 'What is the problem?', 'The plot is about 4 pixels, too few to judge; advise a different data source or ground survey.')])
C['deep']['extra'] = [
 ['Compare a nanosatellite with a large one on mass, cost and lifetime; small ones often last one to five years.', 'Learn why antennas and batteries are the usual limits.'],
 ['Use a free sky-tracking tool to see real passes of small satellites over your town.', 'Note that cloud over the ground station does not stop radio, but weather can affect some links.'],
 ['Check the width of the area each image covers (the swath); wider means fewer passes.', 'Compare spectral bands on a sample image and write what each shows.'],
 ['Keep a data log: file name, date, cloud percent, size and licence.', 'Use small test crops before downloading a whole scene.'],
 ['Plot your index values on a simple chart; a picture of change is more persuasive than a table.', 'Repeat the calculation for a control area that should not have changed.'],
 ['Write one sentence per limit saying how it could mislead a decision.', 'Ask a local expert whether the pattern matches what they see on the ground.'],
 ['Write the headline last, after you have seen all results.', 'Use colour scales that are readable for colour-blind viewers.'],
 ['Offer the reader a follow-up in 30 days with a new image date.', 'Add your method as a short recipe so someone else can repeat it.']]
_np = [['Compare sizes: a one-unit cube measures about 10 centimetres per side, and several units can be joined, so a three-unit craft is roughly 30 centimetres long.', 'Note that small craft usually carry one or two sensors for a narrow job, and trade size for numbers, so a group of ten can revisit a place far more often than one large craft.'], ['A craft in low orbit circles Earth in about 90 minutes at roughly 500 kilometres height, so it passes a given spot only a few times a day or less.', 'Use a free pass-prediction page to list the next five passes over your location, and note time, maximum height in the sky and duration in minutes.'], ['Match band to question: visible light for roads and buildings, near-infrared for plant vigour, thermal for heat, and radar when cloud blocks the view.', "Check pixel size before downloading: a 10-metre pixel cannot show a single car, but it can show a whole field's greenness, so match scale to subject."], ['Search an open archive for your area and date range, filter cloud cover to under 20 percent, and save the scene identifier in your notes for later citation.', 'Read the metadata file for date, sensor, pixel size and processing level before opening the image, because wrong assumptions here carry into every later step.'], ['Compare images from the same season, such as two Junes a year apart, so natural growth cycles do not look like real change.', 'Compute a simple index for both dates, subtract one from the other, and mark pixels that change by more than a stated threshold such as 0.2.'], ['Write a limits box listing cloud cover, pixel size, revisit gap and any ground truth you lack, each with one line on how it could mislead.', 'Where you can, check one result against a photo, a map or a local source; even a single ground check raises confidence more than another hour of processing.'], ['Structure the page as question, one map or chart, three findings in plain words and one recommendation, and keep the whole page under 250 words.', 'Label every chart with date, source and units, and add a scale bar, so nothing on the page needs a spoken explanation.'], ['Keep a log of each project with question, data used, time taken and what you would change, and review it after every third project.', 'Set three 90-day goals, such as one new sensor type, one local partner who uses your results and one published page, and check them monthly.']]
C['mods'] = [(m[0], m[1], list(m[2])+_np[i], m[3], m[4], m[5]) for i, m in enumerate(C['mods'])]
C['intro_add'] = ["You will describe a nanosatellite's main parts and size classes, so you can judge what a small craft can and cannot observe.", "You will predict passes over your location and relate orbit height to revisit time, so you know when fresh data can realistically exist.", "You will choose a light band and pixel size that fit a question, avoiding images too coarse or too costly for the subject.", "You will find open scenes with low cloud, read their metadata and respect their licences, so every dataset you use is documented and citable.", "You will compare two same-season dates with a simple index and a stated threshold, separating real change from ordinary seasonal growth.", "You will list the limits of your data, such as cloud, resolution and missing ground checks, and test one result against a local source.", "You will condense an analysis into a one-page story with a question, a labelled map, three findings and a recommendation a decision maker can use.", "You will test your story on a real reader, log what you would change, and set practical goals for widening your skills."]
